         color: var(--text);
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
           sans-serif;
         line-height: 1.5;
       }

       .app-shell {
         width: min(100%, 28rem);
       }

       .consent-card {
         padding: 2rem;
         border: 1px solid rgba(216, 224, 236, 0.8);
         border-radius: 1.5rem;
         background: rgba(255, 255, 255, 0.94);
         box-shadow: var(--shadow);
         backdrop-filter: blur(12px);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--primary);
         font-size: 0.78rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0 0 0.75rem;
         font-size: clamp(1.85rem, 5vw, 2.4rem);
         line-height: 1.1;
         letter-spacing: -0.04em;
       }

       .intro {
         margin: 0 0 1.75rem;
         color: var(--muted);
       }

       .form-field {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.8rem;
         align-items: start;
         margin-bottom: 1.5rem;
         padding: 1rem;
         border: 1px solid var(--border);
         border-radius: 1rem;
         background: #f9fbff;
       }

       input[type="checkbox"] {
         width: 1.2rem;
         height: 1.2rem;
         margin: 0.16rem 0 0;
         accent-color: var(--primary);
       }

       input[type="checkbox"]:focus-visible,
       button:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       label {
         display: block;
         font-weight: 700;
       }

       .helper-text {
         margin: 0.25rem 0 0;
         color: var(--muted);
         font-size: 0.94rem;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.25rem;
         background: var(--primary);
         color: #ffffff;
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         box-shadow: 0 14px 28px rgba(38, 93, 242, 0.25);
         transition:
           background 160ms ease,
           transform 160ms ease,
           box-shadow 160ms ease;
       }

       button:hover {
         background: var(--primary-dark);
         transform: translateY(-1px);
         box-shadow: 0 18px 34px rgba(38, 93, 242, 0.3);
       }

       button:active {
         transform: translateY(0);
       }

       @media (max-width: 34rem) {
         body {
           padding: 1rem;
         }

         .consent-card {
           padding: 1.5rem;
         }
       }
     </style>
   </head>
   <body>
     <main id="app" class="app-shell" aria-label="Terms consent"></main>

     <script>
       const FormField = () => `
         <div class="form-field">
           <input
             type="checkbox"
             id="terms"
             name="terms"
             required
             aria-describedby="terms-helper"
           >
           <div>
             <label for="terms">I agree to the terms of use</label>
             <p class="helper-text" id="terms-helper">Required to create and manage your account.</p>
           </div>
         </div>
       `;

       const ConsentForm = () => `
         <section class="consent-card" aria-labelledby="consent-title">
           <p class="eyebrow">Consent</p>
           <h1 id="consent-title">Review and accept</h1>
           <p class="intro">Confirm that you agree before continuing.</p>
           <form>
             ${FormField()}
             <button type="submit">Submit agreement</button>
           </form>
         </section>
       `;

       const App = () => ConsentForm();

       document.querySelector("#app").innerHTML = App();
     </script>
   </body>
 </html>

')
